Archive Records As JSON.code:
// Land the raw payload in the data lake, partitioned by date.
putObject(
  // 1) Destination bucket.
  'raw-health-data',
  // 2) Object name / path.
  `openmrs/${new Date().toISOString().slice(0, 10)}/encounters-${$.data.batchId}.json`,
  // 3) Data to upload (serialised as JSON by default).
  $.data.encounters
);

Export Report As CSV.code:
// Write a monthly indicator report to the bucket as CSV.
putObject(
  // 1) Destination bucket.
  'reports',
  // 2) Object name / path.
  `indicators/${$.data.period}/facility-summary.csv`,
  // 3) Array of row objects.
  $.data.rows,
  // 4) Upload options.
  {
    format: 'csv',
    metadata: { 'x-amz-meta-source': 'dhis2' },
  }
);

Create Bucket.code:
// Create a bucket for a new programme's data.
createBucket(
  // 1) Bucket name.
  'cash-transfer-exports',
  // 2) Region.
  'us-east-1',
  // 3) Options.
  { ObjectLocking: true }
);

Tag Object As Processed.code:
// Mark a file as processed so it isn't picked up again.
setObjectTags(
  // 1) Bucket.
  'raw-health-data',
  // 2) Object name.
  $.data.objectName,
  // 3) Tags (overwrites existing tags).
  { status: 'processed', processedBy: 'openfn' }
);

List Objects By Prefix.code:
// List files uploaded under a monthly prefix.
listObjects('raw-health-data', {
  prefix: 'openmrs/2026-04/',
  recursive: true,
});

Get JSON Object.code:
// Read a JSON file from the bucket into state.data.
getObject(
  // 1) Bucket.
  'raw-health-data',
  // 2) Object name.
  $.data.objectName,
  // 3) Parse options.
  { format: 'json' }
);

Get CSV Object.code:
// Read a beneficiary list uploaded as CSV and write it to state.beneficiaries.
getObject('imports', 'beneficiaries/latest.csv', {
  format: 'csv',
  destination: 'beneficiaries',
});
